import{_ as n,C as o,o as t,c as r,a2 as a,b as l,w as s,a as h,E as d,a3 as c}from"./chunks/framework.CZqXuAiL.js";const F=JSON.parse('{"title":"Quick Start","description":"Get Protection Plus watching your node in 60 seconds, then safely move from dry-run to armed enforcement.","frontmatter":{"title":"Quick Start","description":"Get Protection Plus watching your node in 60 seconds, then safely move from dry-run to armed enforcement."},"headers":[],"relativePath":"protection/getting-started/quick-start.md","filePath":"protection/getting-started/quick-start.md","lastUpdated":1785339549000}'),p={name:"protection/getting-started/quick-start.md"};function u(k,e,g,m,y,b){const i=o("Mermaid");return t(),r("div",null,[e[1]||(e[1]=a(`<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><p>This is the recommended path from zero to armed protection. The golden rule: <strong>observe first, enforce second.</strong></p><h2 id="_1-install" tabindex="-1">1. Install <a class="header-anchor" href="#_1-install" aria-label="Permalink to &quot;1. Install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/AnAverageBeing/protection/main/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span></span></code></pre></div><p>Answer the prompts. For your first run, keep <strong><code>Arm enforcement now?</code> → N</strong> so you start in dry-run. See <a href="./installation">Installation</a> for what every question does.</p><h2 id="_2-pull-the-threat-intel" tabindex="-1">2. Pull the threat intel <a class="header-anchor" href="#_2-pull-the-threat-intel" aria-label="Permalink to &quot;2. Pull the threat intel&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> protection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rules</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><p>This downloads the curated YARA rule bundle and the MalwareBazaar SHA-256 blocklist. The on-access antivirus needs this <strong>once</strong> for hash checking — until then the blocklist is simply empty. The daemon refreshes both automatically every 24h afterwards.</p><div class="tip custom-block"><p class="custom-block-title">OPTIONAL SCANNERS</p><p>Two detectors shell out to external CLIs and are no-ops until you install them:</p><ul><li><code>sudo apt install yara</code> — enables YARA scanning in the on-access antivirus (<code>onaccess.yara_check</code>) and the periodic <code>yara</code> sweep (disabled by default).</li><li><code>trivy</code> — enables container-image vulnerability scanning when you set <code>detectors.trivy.enabled: true</code>.</li></ul></div><h2 id="_3-see-what-it-sees" tabindex="-1">3. See what it sees <a class="header-anchor" href="#_3-see-what-it-sees" aria-label="Permalink to &quot;3. See what it sees&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">protection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # config + docker connectivity</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> protection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scan</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # one-off scan, no enforcement</span></span></code></pre></div><p><code>scan</code> runs every detector once against a fresh system snapshot and prints a severity-sorted table. On a clean node you&#39;ll see <code>✓ no threats detected</code>. It never takes action and ignores cooldowns — pure reconnaissance.</p><h2 id="_4-confirm-alerts-work" tabindex="-1">4. Confirm alerts work <a class="header-anchor" href="#_4-confirm-alerts-work" aria-label="Permalink to &quot;4. Confirm alerts work&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">protection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-alert</span></span></code></pre></div><p>You should get a synthetic <strong>critical</strong> test alert in every channel you enabled (Discord/email/webhook). If not, see <a href="./../user-guide/alerts">Alerts</a>.</p><h2 id="_5-watch-it-in-dry-run" tabindex="-1">5. Watch it in dry-run <a class="header-anchor" href="#_5-watch-it-in-dry-run" aria-label="Permalink to &quot;5. Watch it in dry-run&quot;">​</a></h2><p>Let the daemon run and watch what it <em>would</em> do:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> protection</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span></span></code></pre></div><p>In dry-run, enforcement is logged as <code>[dry-run] would run action &quot;neutralize&quot; on …</code> instead of actually firing. Leave it for a few hours (ideally a day) on a real workload to catch false positives and tune thresholds.</p><div class="tip custom-block"><p class="custom-block-title">TUNE WHILE OBSERVING</p><p>If a legitimate workload trips a detector, raise the relevant threshold in <code>/etc/protection/config.yaml</code> (e.g. <code>cpu_threshold</code>, <code>distinct_ports</code>, <code>ratio_threshold</code>) or add the target to the <code>whitelist:</code> section, then <code>sudo systemctl restart protection</code>. See the <a href="./../configuration/reference">Configuration Reference</a>.</p></div><h2 id="_6-arm-enforcement" tabindex="-1">6. Arm enforcement <a class="header-anchor" href="#_6-arm-enforcement" aria-label="Permalink to &quot;6. Arm enforcement&quot;">​</a></h2><p>When the alerts look right and false positives are tuned away, flip the switch:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># /etc/protection/config.yaml</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">general</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  dry_run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><h2 id="_7-restart-to-apply" tabindex="-1">7. Restart to apply <a class="header-anchor" href="#_7-restart-to-apply" aria-label="Permalink to &quot;7. Restart to apply&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> protection</span></span></code></pre></div><p>Protection Plus will now <strong>act</strong> on threats per your <a href="./../user-guide/actions-rules">rules</a>: kill the offending container or process, suspend the Pterodactyl server, quarantine the bomb — and alert every time.</p><hr><h2 id="the-30-second-mental-model" tabindex="-1">The 30-second mental model <a class="header-anchor" href="#the-30-second-mental-model" aria-label="Permalink to &quot;The 30-second mental model&quot;">​</a></h2>`,28)),(t(),l(c,null,{default:s(()=>[d(i,{id:"mermaid-84",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5BInstall%20in%20dry-run%5D%20--%3E%20B%5Brules%20update%5D%0A%20%20%20%20B%20--%3E%20C%5Bscan%20%2B%20test-alert%5D%0A%20%20%20%20C%20--%3E%20D%5BWatch%20via%20journalctl%5D%0A%20%20%20%20D%20--%3E%20E%7BFalse%20positives%3F%7D%0A%20%20%20%20E%20--%3E%7Cyes%7C%20F%5BTune%20%2F%20whitelist%5D%20--%3E%20D%0A%20%20%20%20E%20--%3E%7Cno%7C%20G%5Bdry_run%3A%20false%5D%20--%3E%20H%5Brestart%20%E2%86%92%20Armed%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><strong><a href="./../configuration/reference">Configuration Reference →</a></strong> — every value, default, and when to change it.</li><li><strong><a href="./../user-guide/detection">How Detection Works →</a></strong> — what each detector actually checks.</li><li><strong><a href="./../user-guide/actions-rules">Actions &amp; Rules →</a></strong> — map threats to enforcement.</li></ul>',3))])}const v=n(p,[["render",u]]);export{F as __pageData,v as default};
